const input = $input.first().json;
const leads = Array.isArray(input.leads) ? input.leads : Array.isArray(input.output?.leads) ? input.output.leads : [];
const command = $('Called by Command Center').first().json;
const today = new Date().toISOString().slice(0, 10);
return leads.filter((lead) => lead['Company Name'] || lead.CompanyName || lead.companyName).map((lead) => ({ json: {
  'Company Name': lead['Company Name'] || lead.CompanyName || lead.companyName || '',
  Country: lead.Country || command.country || '',
  'Contact Person': lead['Contact Person'] || lead.ContactPerson || '',
  Email: lead.Email || lead.email || '',
  'Phone Number': lead['Phone Number'] || lead.Phone || lead.phone || '',
  Website: lead.Website || lead.website || '',
  Source: lead.Source || lead.source || '',
  'Product Interest': lead['Product Interest'] || command.product || '',
  'Date Added': today,
  'Last Contact Date': '',
  'Buyer Score': Number(lead['Buyer Score'] || lead.buyer_score || lead.buyerScore || 0),
  Status: 'No Action',
  'Reply Summary': '',
  'Reply Confidence': '',
  'Last Follow-Up Stage': ''
}}));
